// Galápagosreuzenschildpad (zadel- en koepelschild). Laad NA teken_evo9.js: overschrijft x9nandoe, x9gordeldier, x9schildpad
// (zelfde naam, aanroep, schaal s = px per cm en anker = midden onder het dier).
// Werkwijze (recept bibliotheek/dieren/lessen/lessen_pop.md): romp/schild/kop 1:1 overgetrokken van de vlakke rij op
// referentie/dieren/darwin/<dier>.webp (DARWIN_OVERTREK hierboven, in cm), poten/nek/staart als botten met IK; maten uit bronnen
// (zie lessen_pop_darwin.md). Steunvoet staat stil in de wereld; o.vooruit: true schuift het anker met de pas mee (x = startpunt).
// =====================================================================================================
const DarwinPop = (() => {
  const R = Math.PI / 180, frac = v => v - Math.floor(v), lerp = (a, b, k) => a + (b - a) * k, clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const add = (a, b) => [a[0] + b[0], a[1] + b[1]], sub = (a, b) => [a[0] - b[0], a[1] - b[1]], mul = (a, k) => [a[0] * k, a[1] * k];
  const len = a => Math.hypot(a[0], a[1]), rot = (p, an) => [p[0] * Math.cos(an) - p[1] * Math.sin(an), p[0] * Math.sin(an) + p[1] * Math.cos(an)];
  const pol = (an, l) => [Math.cos(an) * l, Math.sin(an) * l];
  function mixHex(a, b, k) { const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16); const c = [16, 8, 0].map(s => Math.round(lerp((pa >> s) & 255, (pb >> s) & 255, k))); return '#' + c.map(v => v.toString(16).padStart(2, '0')).join(''); }
  const ver = c => mixHex(c, '#3E3A36', 0.34); // verre poten: warm-donkere tint (wolfles 6)
  function pad(ctx, P) { ctx.beginPath(); P.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath(); }
  // 2-bots-IK: A -> (knik) -> B, teken +1/-1 kiest de kant van de knik; geeft [knik, rek]
  function ik(A, B, L1, L2, teken) { const d = sub(B, A), D = len(d), rek = D / (L1 + L2); const Dc = clamp(D, Math.abs(L1 - L2) + 1e-3, (L1 + L2) * 0.9999);
    const a = Math.acos(clamp((L1 * L1 + Dc * Dc - L2 * L2) / (2 * L1 * Dc), -1, 1)); const b = Math.atan2(d[1], d[0]) + teken * a; return [add(A, pol(b, L1)), rek]; }
  // buis langs een middenlijn met breedtes (Catmull-Rom niet nodig: botten zijn recht); geeft polygon
  function buis(P, W) { const n = P.length, L = [], Rr = []; for (let i = 0; i < n; i++) { const a = P[Math.max(0, i - 1)], b = P[Math.min(n - 1, i + 1)]; const t = sub(b, a), l = len(t) || 1, nn = [-t[1] / l, t[0] / l]; const w = W[Math.min(W.length - 1, Math.round(i * (W.length - 1) / Math.max(1, n - 1)))] / 2;
      L.push(add(P[i], mul(nn, w))); Rr.push(add(P[i], mul(nn, -w))); }
    // kappen in de juiste draairichting (reptielenles): eind van L naar R om de punt heen, begin van R naar L om de achterkant
    const kap = (c, r, van, richting) => { const o = []; for (let k = 1; k < 8; k++) o.push(add(c, pol(van + richting * Math.PI * k / 8, r))); return o; };
    const t1 = sub(P[n - 1], P[n - 2]), t0 = sub(P[1], P[0]); const a1 = Math.atan2(t1[1], t1[0]), a0 = Math.atan2(t0[1], t0[0]);
    return [...L, ...kap(P[n - 1], W[W.length - 1] / 2, a1 + Math.PI / 2, -1), ...Rr.reverse(), ...kap(P[0], W[0] / 2, a0 - Math.PI / 2, -1)]; }
  function bez(P0, P1, P2, P3, n) { const o = []; for (let i = 0; i <= n; i++) { const t = i / n, u = 1 - t; o.push([u * u * u * P0[0] + 3 * u * u * t * P1[0] + 3 * u * t * t * P2[0] + t * t * t * P3[0], u * u * u * P0[1] + 3 * u * u * t * P1[1] + 3 * u * t * t * P2[1] + t * t * t * P3[1]]); } return o; }
  // overgetrokken lagen tekenen; f = puntafbeelding (cm -> cm)
  function lagen(ctx, L, pal, f) { for (const l of L) { pad(ctx, f ? l.p.map(f) : l.p); ctx.fillStyle = pal[l.c] || '#f0f'; ctx.fill(); } }
  // één tekening = lijst delen {vorm: [punten] (voor de silhouetrand), teken: fn}. Pas 1: lichte rand, pas 2: vlakken.
  function render(ctx, delen, rand, rb) { ctx.save(); ctx.lineJoin = 'round'; ctx.strokeStyle = rand; ctx.lineWidth = rb * 2;
    for (const d of delen) for (const v of (d.vormen || [])) { pad(ctx, v); ctx.stroke(); }
    ctx.restore(); for (const d of delen) d.teken(ctx); }
  // doorzichtig: eerst op een los canvas (wolfles 'doorzichtig')
  function metAlpha(ctx, a, fn) { if (a >= 0.999) return fn(ctx); if (a <= 0.01) return; const c = document.createElement('canvas'); c.width = ctx.canvas.width; c.height = ctx.canvas.height;
    const k = c.getContext('2d'); k.setTransform(ctx.getTransform()); fn(k); ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.globalAlpha *= a; ctx.drawImage(c, 0, 0); ctx.restore(); }
  function oog(ctx, p, r, s, iris) { ctx.save(); ctx.translate(p[0], p[1]); ctx.scale(1 / s, 1 / s); dierOog(ctx, 0, 0, Math.max(1.6, r * s), iris); ctx.restore(); }
  // gangmodel per voet: fase ph (0 = neerzetten), duty, pas S (cm per cyclus), midden xc, hoogte zwaai h; x t.o.v. het lijf
  function voet(ph, duty, S, xc, h, piek = 0.45) { const st = S * duty; if (ph < duty) { const u = ph / duty; return { x: xc + st / 2 - u * st, y: 0, steun: true, u }; }
    const v = (ph - duty) / (1 - duty), x0 = xc - st / 2, x1 = xc + st / 2, m = -S * (1 - duty) * 0.35; // Hermite: begin- en eindsnelheid terug (tegen de loopsnelheid in)
    const h00 = 2 * v * v * v - 3 * v * v + 1, h10 = v * v * v - 2 * v * v + v, h01 = -2 * v * v * v + 3 * v * v, h11 = v * v * v - v * v;
    const w = v < piek ? Math.sin(Math.PI / 2 * v / piek) : Math.cos(Math.PI / 2 * (v - piek) / (1 - piek));
    return { x: h00 * x0 + h10 * m + h01 * x1 + h11 * m, y: -h * w * w, steun: false, v }; }
  return { R, frac, lerp, clamp, add, sub, mul, len, rot, pol, mixHex, ver, pad, ik, buis, bez, lagen, render, metAlpha, oog, voet };
})();

// ----------------------------------------------------------------------------------------------------- grote nandoe
// Bron: hoogte 0,9–1,5 m, 15–30 kg, drie tenen (Smithsonian NZP); tibiotarsus 301,8 mm (n = 3, SIIEPE UFPel 2018);
// tibiotarsus = 0,39–0,46 × heuphoogte bij grote loopvogels, staplengte 0,8–1,2 × heuphoogte, duty bij stappen ±0,55–0,7 (Alexander 2004, PMC1571302).
const NANDOE_DEF = {
  pal: { d: '#5C554F', m: '#857B73', l: '#A89E95', w: '#C6BDB4' }, poot: '#B2A89F', teen: '#5A524C', rand: '#ABA39A',
  heup: [-24, -77], dij: 17.3, tibia: 30.2, tmt: 36, teenL: 12, // cm; heup 77 cm (tibia/heup = 0,39), knie verborgen in de veren
  staan: [[-11, -2.4], [-2, -2.4]], // kogels (teengewricht) van nabije en verre poot in staan (plaat)
  oog: [36.6, -146.4, 1.15],
  gang: { S: 92, duty: 0.62, h: 13, xc: -6, zak: 4.5, bob: 1.4 } // staplengte 46 cm = 0,6 × heuphoogte (0,8 gaf rek 1,22 bij neerzetten; zie lessen_pop_darwin.md)
};
const NandoePop = (() => {
  const P = DarwinPop, D = NANDOE_DEF;
  function been(H, kogel, steun, zwaai, rest) { // dij-hoek: rust 30° omlaag, protractie bij voet naar voren; tibia+tmt met IK (hak naar achter)
    // dijbeen: zwaait mee (protractie bij voet vóór de heup); als de rest van het been dan te kort is, draait de knie naar de voet toe
    const rust = Math.atan2(8.7, 15), voorkeur = rust - 0.012 * (kogel[0] - rest[0]), doel = (D.tibia + D.tmt) * 0.965; let best = null;
    for (let i = -60; i <= 60; i++) { const fa = voorkeur + i * P.R; const K = P.add(H, P.pol(fa, D.dij)); const d = P.len(P.sub(kogel, K));
      const straf = Math.max(0, d - doel) * 40 + Math.abs(i) * 0.02 + (K[0] < H[0] - 4 ? 5 : 0); if (!best || straf < best.straf) best = { straf, K }; }
    const K = best.K;
    const [A, rek] = P.ik(K, kogel, D.tibia, D.tmt, -1); return { H, K, A, B: kogel, rek, steun, zwaai }; }
  function houding(o) { const t = o.t || 0, lopen = o.houding === 'lopen' || o.houding === 'stap'; const G = D.gang;
    if (!lopen) return { dy: 0, kantel: 0, nek: 0, poten: D.staan.map((k, i) => ({ k, steun: true, teen: 0 })) };
    const ph = P.frac(t); const bob = -G.bob * Math.cos(4 * Math.PI * ph); // hoog midden in de steunfase (omgekeerde slinger)
    const poten = [0, 0.5].map(off => { const v = P.voet(P.frac(ph + off), G.duty, G.S, G.xc, G.h, 0.4); const laat = v.steun && v.u > 0.8 ? (v.u - 0.8) / 0.2 : 0;
      return { k: [v.x, -2.4 + v.y - laat * 2.0], steun: v.steun, teen: v.steun ? laat : 1, v: v.v || 0 }; });
    return { dy: G.zak + bob, kantel: 1.2 * P.R * Math.sin(4 * Math.PI * ph), nek: 1.5 * P.R * Math.sin(4 * Math.PI * ph + 0.6), poten, S: G.S }; }
  function teken(ctx, x, y, s, o = {}) { const { kijk = 1, a = 1 } = o; const h = houding(o); const T = DARWIN_OVERTREK.nandoe;
    const shift = o.vooruit && h.S ? h.S * (o.t || 0) * s * kijk : 0;
    P.metAlpha(ctx, a, (c) => { c.save(); c.translate(x + shift, y); c.scale(s * kijk, s);
      const Hc = D.heup, piv = [Hc[0], Hc[1]]; // lijf draait om de heup
      const lijf = p => { const q = P.rot(P.sub(p, piv), h.kantel); return [q[0] + piv[0], q[1] + piv[1] + h.dy]; };
      const nekP = [30, -100]; const nekF = p => { const q = lijf(p); const b = lijf(nekP); const r = P.rot(P.sub(q, b), h.nek); return P.add(b, r); };
      const H = lijf(Hc); const poten = h.poten.map((p, i) => been(H, p.k, p.steun, p.teen, D.staan[i]));
      const delen = [];
      [1, 0].forEach(i => { const b = poten[i]; const kl = i ? P.ver(D.poot) : D.poot, tk = i ? P.ver(D.teen) : D.teen; const tp = h.poten[i].teen;
        const tib = P.buis([b.K, b.A], [6.5, 3.4]), tmt = P.buis([b.A, b.B], [3.0, 2.3]);
        const ta = Math.min(tp * 62 * P.R, Math.asin(P.clamp(-b.B[1] / D.teenL, -1, 1)) - 0.02); // afzetten: teen blijft liggen terwijl de kogel opkomt; teenpunt nooit onder de grond 
        const t1 = P.add(b.B, P.pol(ta, D.teenL)), t2 = P.add(b.B, P.pol(ta + 0.25, D.teenL * 0.72));
        const teen = P.buis([b.B, t1], [2.4, 1.2]), teen2 = P.buis([b.B, t2], [2.0, 1.0]);
        delen.push({ vormen: [tib, tmt, teen, teen2], teken: k => { [teen2, tmt, tib, teen].forEach(v => { P.pad(k, v); k.fillStyle = kl; k.fill(); });
          k.beginPath(); k.arc(b.A[0], b.A[1], 1.9, 0, 6.283); k.fill(); // hak
          [t1, t2].forEach(tt => { k.beginPath(); k.arc(tt[0], tt[1], 0.7, 0, 6.283); k.fillStyle = tk; k.fill(); }); } }); });
      const romp = T.romp, nek = T.nek;
      delen.push({ vormen: [romp[0].p.map(lijf)], teken: k => P.lagen(k, romp, D.pal, lijf) });
      delen.push({ vormen: [nek[0].p.map(nekF)], teken: k => { P.lagen(k, nek, D.pal, nekF); P.oog(k, nekF(D.oog), D.oog[2], s, '#3A2A1E'); } });
      P.render(c, delen, D.rand, 1.1 / s);
      if (o.skelet) skelet(c, poten, s);
      c.restore(); });
    return h; }
  function skelet(c, poten, s) { c.lineWidth = 2 / s; poten.forEach((b, i) => { c.strokeStyle = i ? '#3070D0' : '#D03030'; c.beginPath(); c.moveTo(b.H[0], b.H[1]); c.lineTo(b.K[0], b.K[1]); c.lineTo(b.A[0], b.A[1]); c.lineTo(b.B[0], b.B[1]); c.stroke(); [b.H, b.K, b.A, b.B].forEach(p => { c.beginPath(); c.arc(p[0], p[1], 3 / s, 0, 6.283); c.fillStyle = c.strokeStyle; c.fill(); }); }); }
  function meet(o) { const h = houding(o); const H = [D.heup[0], D.heup[1] + h.dy]; return h.poten.map((p, i) => been(H, p.k, p.steun, p.teen, D.staan[i])); }
  return { teken, houding, meet, D };
})();

// ----------------------------------------------------------------------------------------------------- negenbandgordeldier
// Bron: kop-romp 38–58 cm, staart 26–53 cm, schildhoogte 15–25 cm, 2,5–6,5 kg; lange klauwen aan de middelste voortenen (Wikipedia);
// kop-romp 38–43, staart 36–41 cm (Brazos Bend SP). Loopt 'sjokkend'; stapvolgorde lateraal (Hildebrand 1980: de meeste viervoeters;
// van de gordeldieren loopt alleen het reuzengordeldier diagonaal), ook lateraal en diagonaal gezien bij klimmen (Redalyc 2019).
const GORDEL_DEF = {
  pal: { d: '#66584E', m: '#94836F', l: '#B7A391', w: '#D3BDAA' }, poot: '#6C5C51', klauw: '#D8C8B6', rand: '#B4A493',
  staart: { wortel: [-16.4, -12.0], L: 36, dik: 3.8 }, // plaat had de staart te kort (17 cm): bron wint
  heup: [-9.5, -9.6], schouder: [9.5, -9.0], dij: 4.9, scheen: 4.5, voet: 3.0, arm: 4.4, onderarm: 4.0, hand: 2.2,
  staan: { A: -9.5, V: 10.5 }, oog: [21.4, -13.3, 0.55],
  gang: { S: 13, duty: 0.68, h: 1.9, bob: 0.25, fase: { AN: 0, VN: 0.25, AF: 0.5, VF: 0.75 } }
};
const GordelPop = (() => {
  const P = DarwinPop, D = GORDEL_DEF;
  const P_bw = p => { const xs = p.map(q => q[0]); return Math.max(...xs) - Math.min(...xs); }, P_top = p => Math.min(...p.map(q => q[1]));
  const P_opp = p => { let a = 0; for (let i = 0, j = p.length - 1; i < p.length; j = i++) a += (p[j][0] + p[i][0]) * (p[j][1] - p[i][1]); return Math.abs(a / 2); };
  function poot(top, voorP, steun, voor, schuif) { // voor: schouder schuift mee (scapula), elleboog naar achter (+1), knie naar voren (-1)
    if (voor) { const T = [top[0] + schuif, top[1]]; const pols = [voorP[0] - 0.4, voorP[1] - 1.3]; const [E, rek] = P.ik(T, pols, D.arm, D.onderarm, 1); return { T, M: E, W: pols, B: voorP, rek, voor }; }
    const hak = [voorP[0] - 2.4, voorP[1] - (steun ? 1.2 : 1.6)]; const [K, rek] = P.ik(top, hak, D.dij, D.scheen, -1); return { T: top, M: K, W: hak, B: voorP, rek, voor }; }
  function houding(o) { const t = o.t || 0, lopen = o.houding === 'lopen' || o.houding === 'stap'; const G = D.gang;
    if (!lopen) return { dy: 0, kantel: 0, staart: 0, voeten: { AN: [D.staan.A, 0], AF: [D.staan.A + 1.5, 0], VN: [D.staan.V, 0], VF: [D.staan.V + 1.5, 0] }, schuif: { VN: 0, VF: 0 } };
    const ph = P.frac(t), voeten = {}, schuif = {};
    for (const k of ['AN', 'AF', 'VN', 'VF']) { const vo = k[0] === 'V'; const v = P.voet(P.frac(ph - G.fase[k]), G.duty, G.S, vo ? D.staan.V - 0.6 : D.staan.A + 1.6, G.h, 0.45); voeten[k] = [v.x, v.y]; schuif[k] = vo ? 0.3 * (v.x - D.staan.V + 0.6) : 0; }
    return { dy: G.bob * Math.cos(4 * Math.PI * ph), kantel: 0.8 * P.R * Math.sin(2 * Math.PI * ph), staart: 2.5 * P.R * Math.sin(2 * Math.PI * ph + 1), voeten, schuif, S: G.S }; }
  function staartVorm(h) { const S = D.staart, w = S.wortel, tip = [w[0] - S.L * 0.9, -0.9]; const sw = h.staart * 10; // staart hangt naar achter-omlaag, punt sleept bijna over de grond
    const P0 = w, P1 = P.add(w, P.pol(150 * P.R + h.staart, S.L * 0.32)), P2 = [tip[0] + S.L * 0.3, tip[1] - 1.6 + sw * 0.3], P3 = [tip[0], tip[1] + sw * 0.05];
    const pts = P.bez(P0, P1, P2, P3, 16), W = pts.map((_, i) => S.dik * (1 - 0.86 * i / 16)); return { pts, W }; }
  function teken(ctx, x, y, s, o = {}) { const { kijk = 1, a = 1 } = o; const h = houding(o); const T = DARWIN_OVERTREK.gordeldier.romp.concat(DARWIN_OVERTREK.gordeldier.kop.slice(0)); const TK = DARWIN_OVERTREK.gordeldier.kop;
    const shift = o.vooruit && h.S ? h.S * (o.t || 0) * s * kijk : 0;
    P.metAlpha(ctx, a, (c) => { c.save(); c.translate(x + shift, y); c.scale(s * kijk, s);
      const lijf = p => { const q = P.rot(p, h.kantel); return [q[0], q[1] + h.dy]; };
      const pt = {}; for (const k of ['AF', 'VF', 'AN', 'VN']) { const vo = k[0] === 'V'; pt[k] = poot(lijf(vo ? D.schouder : D.heup), h.voeten[k], h.voeten[k][1] > -0.01, vo, h.schuif[k] || 0); }
      const delen = [];
      const st = staartVorm(h); const stP = st.pts.map(lijf); const stV = P.buis(stP, st.W);
      delen.push({ vormen: [stV], teken: k2 => { P.pad(k2, stV); k2.fillStyle = D.pal.m; k2.fill(); k2.save(); P.pad(k2, stV); k2.clip(); // ringen
        for (let i = 1; i < stP.length - 1; i++) { const a0 = stP[i], a1 = stP[i + 1], w = st.W[i] * 0.6, dir = P.sub(a1, a0), nn = P.mul([-dir[1], dir[0]], 1 / (P.len(dir) || 1));
          const q = (u, k) => P.add(P.add(a0, P.mul(dir, u)), P.mul(nn, k * w * 1.2)); k2.beginPath(); k2.moveTo(...q(0.1, -1)); k2.lineTo(...q(0.45, -1)); k2.lineTo(...q(0.55, 1)); k2.lineTo(...q(0.2, 1)); k2.closePath(); k2.fillStyle = D.pal.d; k2.fill(); }
        k2.beginPath(); stP.forEach((p, i) => { const w = st.W[i] * 0.22; i ? k2.lineTo(p[0], p[1] - w) : k2.moveTo(p[0], p[1] - w); }); k2.strokeStyle = D.pal.l; k2.lineWidth = 0.5; k2.stroke(); k2.restore(); } });
      for (const k of ['AF', 'VF', 'AN', 'VN']) { const b = pt[k], ver = k[1] === 'F'; const kl = ver ? P.ver(D.poot) : D.poot;
        const v1 = P.buis([b.T, b.M], b.voor ? [4.2, 3.0] : [5.6, 3.4]), v2 = P.buis([b.M, b.W], b.voor ? [3.0, 2.4] : [3.2, 2.4]), v3 = P.buis([b.W, b.B, P.add(b.B, [b.voor ? 2.2 : 2.0, 0])], [2.4, 2.0, 1.3]);
        delen.push({ vormen: [v1, v2, v3], teken: k2 => { [v1, v2, v3].forEach(v => { P.pad(k2, v); k2.fillStyle = kl; k2.fill(); });
          k2.strokeStyle = ver ? P.ver(D.klauw) : D.klauw; k2.lineWidth = 0.32; k2.lineCap = 'round'; for (let i = 0; i < 3; i++) { const bx = b.B[0] + (b.voor ? 1.0 : 0.6) + i * 0.55; k2.beginPath(); k2.moveTo(bx, b.B[1] - 0.3); k2.quadraticCurveTo(bx + 0.7, b.B[1] - 0.2, bx + (b.voor ? 1.3 : 0.9), b.B[1] + 0.05); k2.stroke(); } } }); }
      const TR = DARWIN_OVERTREK.gordeldier.romp;
      delen.push({ vormen: [TR[0].p.map(lijf), TK[0].p.map(lijf)], teken: k2 => { P.lagen(k2, TR.filter((l, i) => !i || l.c === 'd' || P_bw(l.p) < 1.6 || P_top(l.p) > -4.5), D.pal, lijf); P.lagen(k2, TK, D.pal, lijf); // grote lichte vlekken weg: alleen bandranden en de onderrand
        k2.save(); P.pad(k2, TR[0].p.map(lijf)); k2.clip(); k2.fillStyle = D.pal.l; // schildplaatjes als rustige rijen puntjes (plaat: regelmatig raster), niet op kop en banden
        for (let gx = -16; gx < 13; gx += 1.05) for (let gy = -14.6; gy < -4.5; gy += 1.05) { if (gx > -3.8 && gx < 4.6) continue; const q = lijf([gx + ((Math.round(gy / 1.05) & 1) ? 0.52 : 0), gy]); k2.beginPath(); k2.arc(q[0], q[1], 0.2, 0, 6.283); k2.fill(); }
        k2.restore(); P.oog(k2, lijf(D.oog), D.oog[2], s, '#20160F'); } });
      P.render(c, delen, D.rand, 0.35 / Math.max(0.5, s / 3));
      if (o.skelet) { c.lineWidth = 1.5 / s; for (const k in pt) { const b = pt[k]; c.strokeStyle = k[1] === 'F' ? '#3070D0' : '#D03030'; c.beginPath(); [b.T, b.M, b.W, b.B].forEach((p, i) => i ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1])); c.stroke(); } }
      c.restore(); });
    return h; }
  function meet(o) { const h = houding(o); const r = {}; for (const k of ['AF', 'VF', 'AN', 'VN']) { const vo = k[0] === 'V'; const top = vo ? D.schouder : D.heup; r[k] = poot([top[0], top[1] + h.dy], h.voeten[k], h.voeten[k][1] > -0.01, vo, h.schuif[k] || 0); } return r; }
  return { teken, houding, meet, D };
})();

// ----------------------------------------------------------------------------------------------------- reuzenschildpad
// Bron: zadelschild = voorrand van het schild sterk opgetild, langere en dunnere nek en poten, kleiner (Española max ±75 cm schild;
// Wikipedia Hood Island giant tortoise; SDZG factsheet; techno-science); langere nek bij zadelruggen (Chiari e.a. 2017, Sci Rep 7:15787);
// de nek gestrekt omhoog bij voedsel hoog en bij rangordegevechten (Fritts 1984; SDZG); koepelschildpadden: kortere nek en poten, zwaarder.
const SCHILD_DEF = {
  zadel: { L: 80, wortel: [6, -34], kantelOp: -6, kantelNeer: 1.5, spil: [-22, 0], nekB: [15, 12.5, 10.5], oog: [58.0, -50.2, 1.0],
    // nekstand: [r, hoek] van de kop-aanzet t.o.v. de nekwortel, kophoek, hoek van de nek bij de kop, uitgang uit het schild (hoek, lengte)
    // 0 = plaat fig. 3 (nek half), 1 = fig. 4 (omhoog), -1 = fig. 2 (omlaag)
    rust: { r: 45.7, h: -15, kop: 0, eind: -31, uit: -3, a: 13 }, op: { r: 64, h: -69, kop: -22, eind: -74, uit: -58, a: 17 }, neer: { r: 40.5, h: 32, kop: 52, eind: 58, uit: 18, a: 13 },
    kopAanzet: [50.2, -45.8] },
  koepel: { L: 110, wortel: [20, -46], kantelOp: -2, kantelNeer: 1, spil: [-30, 0], nekB: [17, 14, 12], oog: [66.7, -70.8, 1.1],
    rust: { r: 48.2, h: -28.6, kop: 0, eind: -28, uit: -18, a: 14 }, op: { r: 53, h: -44, kop: -10, eind: -48, uit: -36, a: 14 }, neer: { r: 46, h: 6, kop: 35, eind: 30, uit: 0, a: 12 },
    kopAanzet: [62.3, -69.1] }
};
const SCHILD_PAL = { sd: '#57524D', sz: '#423D38', naad: '#7B746C', sk: '#8A837C', skl: '#B9AFA3' };
const SchildPop = (() => {
  const P = DarwinPop;
  function stand(D, nek) { const a = nek >= 0 ? D.rust : D.neer, b = nek >= 0 ? D.op : D.rust, k = nek >= 0 ? nek : nek + 1; const o = {}; for (const key in a) o[key] = P.lerp(a[key], b[key], k); return o; }
  function teken(ctx, vorm, x, y, s, o = {}) { const { kijk = 1, a = 1 } = o; const D = SCHILD_DEF[vorm], T = DARWIN_OVERTREK[vorm];
    const nek = P.clamp(o.nek == null ? (vorm === 'zadel' ? 1 : 0) : o.nek, -1, 1); const st = stand(D, nek);
    const kant = (nek >= 0 ? D.kantelOp * nek : D.kantelNeer * -nek) * P.R; // schild kantelt om de achtervoeten; voorpoten strekken
    P.metAlpha(ctx, a, (c) => { c.save(); c.translate(x, y); c.scale(s * kijk, s);
      const sch = p => P.add(P.rot(P.sub(p, D.spil), kant), D.spil);
      const poot = p => { const f = P.clamp(-p[1] / 22, 0, 1); const q = sch(p); return [P.lerp(p[0], q[0], f), P.lerp(p[1], q[1], f)]; }; // voet blijft staan, bovenkant gaat mee met het schild
      const W = sch(D.wortel); const J = P.add(W, P.pol(st.h * P.R, st.r)); const dE = P.pol(st.eind * P.R, 1), dU = P.pol((st.uit + kant / P.R) * P.R, 1);
      const nekP = P.bez(W, P.add(W, P.mul(dU, st.a)), P.sub(J, P.mul(dE, st.a * 0.9)), J, 18); const nekV = P.buis(nekP, D.nekB);
      const kopRot = st.kop * P.R; const kopF = p => P.add(J, P.rot(P.sub(p, D.kopAanzet), kopRot));
      const delen = [];
      delen.push({ vormen: [T.achter[0].p.map(poot)], teken: k => P.lagen(k, T.achter, SCHILD_PAL, poot) });
      delen.push({ vormen: [T.voor[0].p.map(poot)], teken: k => P.lagen(k, T.voor, SCHILD_PAL, poot) });
      delen.push({ vormen: [nekV], teken: k => { P.pad(k, nekV); k.fillStyle = SCHILD_PAL.sk; k.fill(); // keel = lichte band aan de onderkant (tegenover de rug)
        const n = nekP.length, keel = []; for (let i = 0; i < n; i++) { const pa = nekP[Math.max(0, i - 1)], pb = nekP[Math.min(n - 1, i + 1)], t = P.sub(pb, pa), l = P.len(t) || 1, nn = [t[1] / l, -t[0] / l];
          const w = D.nekB[Math.min(D.nekB.length - 1, Math.round(i * (D.nekB.length - 1) / (n - 1)))] / 2; keel.push([P.add(nekP[i], P.mul(nn, -w * 0.4)), P.add(nekP[i], P.mul(nn, -w * 1.0))]); }
        k.save(); P.pad(k, nekV); k.clip(); P.pad(k, [...keel.map(q => q[0]), ...keel.map(q => q[1]).reverse()]); k.fillStyle = SCHILD_PAL.skl; k.fill();
        k.strokeStyle = P.mixHex(SCHILD_PAL.sk, '#3E3A36', 0.25); k.lineWidth = 0.35; for (let i = 3; i < n - 3; i += 3) { const q = nekP[i], t = P.sub(nekP[i + 1], nekP[i - 1]), l = P.len(t) || 1, nn = [t[1] / l, -t[0] / l]; const w = D.nekB[1] * 0.42;
          k.beginPath(); k.moveTo(...P.add(q, P.mul(nn, w))); k.quadraticCurveTo(...P.add(P.add(q, P.mul(t, -0.25 / l * 2)), P.mul(nn, w * 0.3)), ...P.add(q, P.mul(nn, -w * 0.2))); k.stroke(); } k.restore(); } });
      delen.push({ vormen: [T.schild[0].p.map(sch)], teken: k => P.lagen(k, T.schild, SCHILD_PAL, sch) });
      delen.push({ vormen: [T.kop[0].p.map(kopF)], teken: k => { P.lagen(k, T.kop, SCHILD_PAL, kopF); P.oog(k, kopF(D.oog), D.oog[2], s, '#2A2420'); } });
      P.render(c, delen, '#A39B92', 1.1 / s);
      if (o.skelet) { c.strokeStyle = '#D03030'; c.lineWidth = 2 / s; c.beginPath(); nekP.forEach((p, i) => i ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1])); c.stroke(); [W, J, D.spil].forEach(p => { c.beginPath(); c.arc(p[0], p[1], 4 / s, 0, 6.283); c.fillStyle = '#D03030'; c.fill(); }); }
      c.restore(); });
    return { nek, kop: st }; }
  return { teken, stand };
})();

// ----------------------------------------------------------------------------------------------------- wrappers (zelfde naam en aanroep als teken_evo9.js)
// o.houding: 'staan' (standaard) | 'lopen' (nandoe, gordeldier; met o.t = fase 0–1, ook > 1 doorlopend; o.vooruit: true = steunvoet vast in de wereld)
// x9schildpad: o.nek -1 (omlaag) … 0 (half, plaat) … 1 (omhoog); zonder o.nek staat het zadelschild met de nek omhoog (zoals het goedgekeurde storyboard), het koepelschild op 0.
x9nandoe = function (ctx, x, y, s, o = {}) { return NandoePop.teken(ctx, x, y, s, o); };
x9gordeldier = function (ctx, x, y, s, o = {}) { return GordelPop.teken(ctx, x, y, s, o); };
x9schildpad = function (ctx, vorm, x, y, s, o = {}) { return SchildPop.teken(ctx, vorm === 'zadel' ? 'zadel' : 'koepel', x, y, s, o); };
